.dg-card, .dg-phase, .dg-review { border: 1px solid var(--rule); border-radius: 10px; padding: 14px 16px; display: flex; flex-direction: column; gap: 4px; }
.dg-card ul { margin: 8px 0 0; padding-left: 18px; font-size: 13px; color: var(--fg-soft); }
