:root {
  --bg: #fcfcfd;
  --surface: #ffffff;
  --fg: #0a0a0f;
  --fg-soft: #2e2e38;
  --muted: #5f5f6a;
  --rule: #e3e3ea;
  --rule-soft: #f1f1f5;
  --accent: #4a3bef;       --accent-soft: #efedff;
  --ok:     #047a44;       --ok-soft:     #e6f5ed;
  --info:   #1957c4;       --info-soft:   #e7f0fd;
  --warn:   #8b4a05;       --warn-soft:   #fbf0e0;
  --danger: #a82a3f;       --danger-soft: #fbe6ea;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0b0b10; --surface: #15151c;
    --fg: #f4f4f7;
    --fg-soft: #d6d6dd;
    --muted: #9d9dab;
    --rule: #2a2a35; --rule-soft: #1c1c24;
    --accent: #a99dff;       --accent-soft: #2a2548;
    --ok:     #6fd4a0;       --ok-soft:     #122922;
    --info:   #8eb8ff;       --info-soft:   #14233b;
    --warn:   #f0a35a;       --warn-soft:   #2a1f12;
    --danger: #f08597;       --danger-soft: #29151b;
  }
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: var(--bg); color: var(--fg); }
body {
  font: 16px/1.65 "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-feature-settings: "cv11", "ss01", "ss03", "kern", "liga";
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
code, pre { font-family: ui-monospace, SFMono-Regular, "JetBrains Mono", Menlo, monospace; }

.layout { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; max-width: 1200px; margin: 0 auto; }
.layout > * { min-width: 0; }

aside {
  position: sticky; top: 0; align-self: start; height: 100vh; overflow-y: auto;

